SELECT membership_id
FROM workspace_member
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}

SELECT EXISTS(
  SELECT 1
  FROM workspace_member
  WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
    AND status IN ('active', 'pending')
)

SELECT user_id FROM workspace_member WHERE workspace_id = #{workspaceId} AND status IN ('active', 'pending') AND user_id IN
#{userId}
ORDER BY user_id

SELECT COUNT(*)
FROM workspace_member
WHERE workspace_id = #{workspaceId}
  AND status = 'active'
  AND user_id IN

    #{memberId}

SELECT EXISTS(
  SELECT 1
  FROM workspace_member
  WHERE workspace_id = #{workspaceId} AND role_id = #{roleId}
)

SELECT id
FROM workspace
WHERE id > #{afterId}
ORDER BY id
LIMIT #{limit}

SELECT w.id, w.org_id, w.name, w.slug, w.timezone,
       w.identity_version AS identityVersion, w.created_at, w.updated_at
FROM workspace w
JOIN organization o ON o.id = w.org_id
WHERE w.org_id = #{orgId}
  AND w.id > #{afterWorkspaceId}
  AND w.lifecycle_state = 'active'
  AND o.lifecycle_state = 'active'
ORDER BY w.id
LIMIT #{limit}

WITH ranked_memberships AS ( SELECT wm.workspace_id AS workspaceId, u.id AS userId, u.display_name AS displayName, u.profile_picture_url AS profilePictureUrl, COALESCE(wr.name, wm.role) AS role, wm.role_id AS roleId, wm.status AS status, ROW_NUMBER() OVER (PARTITION BY wm.workspace_id ORDER BY u.id) AS memberRow, COUNT(*) OVER (PARTITION BY wm.workspace_id) AS memberCount FROM workspace_member wm JOIN workspace w ON w.id = wm.workspace_id JOIN organization o ON o.id = w.org_id JOIN app_user u ON u.id = wm.user_id LEFT JOIN workspace_role wr ON wr.id = wm.role_id AND wr.workspace_id = wm.workspace_id WHERE w.org_id = #{orgId} AND w.id IN
#{workspaceId}
AND w.lifecycle_state = 'active' AND o.lifecycle_state = 'active' AND wm.status IN ('active', 'pending') AND EXISTS ( SELECT 1 FROM workspace_member actor_membership WHERE actor_membership.workspace_id = wm.workspace_id AND actor_membership.user_id = #{actorId} AND actor_membership.status = 'active' ) ) SELECT workspaceId, userId, displayName, profilePictureUrl, role, roleId, status, memberCount > #{memberLimit} AS rosterTruncated FROM ranked_memberships WHERE memberRow <= #{memberLimit} ORDER BY workspaceId, userId

mapper.update:
UPDATE workspace_member
SET role = #{role}, role_id = NULL, grant_authorization_version = 1
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
